<html>
<head>
<script>
function getParameterByName(name, url = window.location.href) {
    name = name.replace(/[\[\]]/g, '\\$&');
    var regex = new RegExp('[?&]' + name + '(=([^&#]*)|&|#|$)'),
        results = regex.exec(url);
    if (!results) return null;
    if (!results[2]) return '';
    return decodeURIComponent(results[2].replace(/\+/g, ' '));
}
function updateParameter() {
    var parameterName = "param1";
    var newParameterValue = "newValue";
    var url = window.location.href;
    var newUrl = url.replace(new RegExp("(?:\\?|&)" + parameterName + "(=([^&#]*)|&|#|$)"), "$1" + newParameterValue);
    window.history.pushState({}, "", newUrl);
}
</script>
</head>
<body>
    <button onclick="updateParameter()">Update Parameter</button>
    <p>Current URL parameter value for "param1": <span id="parameterValue"></span></p>
    <script>
        function updateParameterValue() {
            var parameterName = "param1";
            var url = window.location.href;
            var parameterValue = getParameterByName(parameterName, url);
            document.getElementById("parameterValue").innerText = parameterValue;
        }
        updateParameterValue();
    </script>
</body>
